/* =============================== CHAPTER 3 =============================== */
/* 3.1 framing */
lazy("fr-chart",()=>{const el=$("#fr-chart");const N=96,vals=Array.from({length:N},(_,i)=>{const t=i/N;return Math.max(30,Math.round(300*Math.exp(-((t-.42)**2)/.018)+120*Math.exp(-((t-.2)**2)/.004)+60+40*Math.sin(i*1.7)))});let mode="toll";
 const draw=()=>{const W=svgW(el),H=300,ml=12,mr=12,mt=50,mb=28,pw=W-ml-mr,ph=H-mt-mb,bw=pw/N,mx=Math.max(...vals);let s=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="${H}" role="img" aria-label="Same data, two framings">`;
  if(mode==="toll"){s+=`<rect width="${W}" height="${H}" fill="#F7F3EE"/><text x="${W/2}" y="28" text-anchor="middle" font-family="Georgia,serif" font-size="22" font-weight="700" fill="#5A0A0A">A bloody toll</text>`;vals.forEach((v,i)=>{s+=`<rect x="${ml+i*bw}" y="${mt}" width="${bw*.9}" height="${v/mx*ph}" fill="#B3141B"/>`});s+=`<line x1="${ml}" x2="${W-mr}" y1="${mt}" y2="${mt}" stroke="#5A0A0A" stroke-width="2"/>`}
  else{s+=`<rect width="${W}" height="${H}" fill="#F3F7FA"/><text x="${W/2}" y="28" text-anchor="middle" font-family="Georgia,serif" font-size="22" font-weight="700" fill="#0E4A6B">Deaths on the decline</text>`;vals.forEach((v,i)=>{s+=`<rect x="${ml+i*bw}" y="${mt+ph-v/mx*ph}" width="${bw*.9}" height="${v/mx*ph}" fill="#2D8FC1"/>`});s+=`<line x1="${ml}" x2="${W-mr}" y1="${mt+ph}" y2="${mt+ph}" stroke="#0E4A6B" stroke-width="2"/>`}
  s+=`<text x="${ml}" y="${H-8}" font-size="11" fill="#666">Start</text><text x="${W-mr}" y="${H-8}" text-anchor="end" font-size="11" fill="#666">End · illustrative monthly counts</text>`;el.innerHTML=s+"</svg>"};
 seg("fr-mode",m=>{mode=m;draw()});draw();new ResizeObserver(()=>draw()).observe(el)});

