const TILES={"Kedah":[1,0],"Kelantan":[2,0],"Penang":[0,1],"Perak":[1,1],"Pahang":[2,1],"Terengganu":[3,1],"Selangor":[1,2],"Kuala Lumpur":[2,2],"Melaka":[1,3],"Negeri Sembilan":[2,3],"Johor":[2,4],"Sarawak":[5,3],"Sabah":[6,2]};
const ABBR={"Kedah":"KDH","Kelantan":"KTN","Penang":"PNG","Perak":"PRK","Pahang":"PHG","Terengganu":"TRG","Selangor":"SGR","Kuala Lumpur":"KUL","Melaka":"MLK","Negeri Sembilan":"NSN","Johor":"JHR","Sarawak":"SWK","Sabah":"SBH"};
